SELECT sm.id AS master_id,sm.title,sm.track,sm.disc,sm.album_id,a.name AS album_name FROM song_masters sm JOIN albums a ON a.id=sm.album_id WHERE sm.album_id!='pending-uploads' AND lower(trim(sm.title)) IN ('春·忆','春日游','昨日樱','最乐观者如是说','最后的留守者','最终的开创者','最终还是','最近啊','月光','月兔の唄','月面旅人','有时p - 哽 咽，难 言。','有时p; 洛天依 - 我〇了曾经的我们','有时p; 洛天依 - 昨天无痛觉的雨','有时p; 洛天依 - 洛阳！洛阳！','有时p; 洛天依 - 纸糖','未命名剧本','未来·未来','某年某月某日','树','树·伴奏','栖凰','格兰芬多印象曲','格兰芬多印象曲·伴奏','桜色の夢と、私と君','梦醉酒醒','此间盈满','比绫星','水瓶座','永恒人间','沉默的守护者','没有蓝莓也没有酒','洛阳怀','活！','流入疑雨的晴') ORDER BY sm.title,sm.album_id